 test("bookings far apart do not clash", () => {
   expect(
@@ -12,3 +13,44 @@ test("a booking inside another clashes", () => {
     overlaps({ from: "2026-03-01", to: "2026-03-10" }, { from: "2026-03-04", to: "2026-03-06" }),
   ).toBe(true);
 });
+
+function databaseWithLoans(): Database {
+  const db = new Database(":memory:");
+  db.exec(
+    "CREATE TABLE loans (id TEXT, item_id TEXT, out_date TEXT, due_date TEXT, returned_date TEXT);" +
+      "CREATE TABLE reservations (id TEXT, item_id TEXT, from_date TEXT, to_date TEXT);" +
+      "INSERT INTO loans VALUES ('L-101','drill-01','2026-03-06','2026-03-13',NULL);" +
+      "INSERT INTO loans VALUES ('L-090','drill-01','2026-03-01','2026-03-13','2026-03-10');",
+  );
+  return db;
+}
+
+test("a booking that starts on the date another ends overlaps it", () => {
+  expect(
+    overlaps({ from: "2026-03-06", to: "2026-03-13" }, { from: "2026-03-13", to: "2026-03-15" }),
+  ).toBe(true);
+});
+
+test("a booking that ends on the date another starts overlaps it", () => {
+  expect(
+    overlaps({ from: "2026-03-13", to: "2026-03-15" }, { from: "2026-03-10", to: "2026-03-13" }),
+  ).toBe(true);
+});
+
+test("a pickup on the due date of an unreturned loan clashes with that loan", () => {
+  const db = databaseWithLoans();
+  expect(clashes(db, "drill-01", { from: "2026-03-13", to: "2026-03-15" })).toEqual(["L-101"]);
+});
+
+test("a returned loan is not listed among the clashes", () => {
+  const db = databaseWithLoans();
+  const found = clashes(db, "drill-01", { from: "2026-03-13", to: "2026-03-15" });
+  expect(found).not.toContain("L-090");
+  expect(found).toContain("L-101");
+});
+
+test("a pickup the day after the due date has no clash with that loan", () => {
+  const db = databaseWithLoans();
+  expect(clashes(db, "drill-01", { from: "2026-03-14", to: "2026-03-16" })).toEqual([]);
+  expect(clashes(db, "drill-01", { from: "2026-03-13", to: "2026-03-13" })).toEqual(["L-101"]);
+});

